 select t.id,'constant','forte','Angiospermes basales (magnoliidees). Feuilles alternes distiques, simples, entieres, sans stipules, souvent aromatiques. Fleurs trimeres, perianthe peu differencie (tepaloide); nombreuses etamines + carpelles libres (apocarpe) sur receptacle bombe. Fruits agreges/multiples charnus (corossol, cachiman). Plantes aromatiques (huiles essentielles); chimie: alcaloides aporphines, acetogenines.' from plant_patterns.taxa t where t.scientific_name='Annonaceae' and t.rank='famille'
 and not exists (select 1 from plant_patterns.taxon_trait_assertions a where a.taxon_id=t.id and a.note like 'Angiospermes basales%');
create temporary table _a(b text,o text,n text,u text);
 select b,nullif(u,''),(select id from plant_patterns.organs where code=o),n,'William Cinea','© William Cinea',case when u<>'' then 'published' else 'draft' end from _a on conflict (code) do nothing;
 select 'PP-ANOBS-'||substr(b,7),(select id from plant_patterns.organs where code=o),'identifie' from _a on conflict (code) do nothing;
 select m.id,o.id from _a a join plant_patterns.media m on m.code=a.b join plant_patterns.observations o on o.code='PP-ANOBS-'||substr(a.b,7);
 select o.id,'Annonaceae','William Cinea',a.n,'forte','validee' from _a a join plant_patterns.observations o on o.code='PP-ANOBS-'||substr(a.b,7);
drop table _a;;
